def goodIntegers(l, r, k):
    # ways[length][d] = number of digit strings of that length starting with
    # digit d in which every adjacent pair differs by at most k
    MAXLEN = 17
    ways = [[0] * 10 for _ in range(MAXLEN + 1)]
    for d in range(10):
        ways[1][d] = 1
    for length in range(2, MAXLEN + 1):
        for d in range(10):
            total = 0
            for e in range(10):
                if abs(d - e) <= k:
                    total += ways[length - 1][e]
            ways[length][d] = total

    # count(N) = number of good integers in [1, N]
    def count(N):
        if N <= 0:
            return 0
        s = [int(ch) for ch in str(N)]
        D = len(s)
        total = 0
        # Numbers with fewer digits: any non-zero leading digit
        for length in range(1, D):
            for d in range(1, 10):
                total += ways[length][d]
        # Numbers with exactly D digits that are <= N: fix a prefix equal to N,
        # then place a strictly smaller digit and let the rest be free
        for i in range(D):
            for d in range(1 if i == 0 else 0, s[i]):
                if i > 0 and abs(d - s[i - 1]) > k:
                    continue
                total += ways[D - i][d]
            # The prefix of N itself must stay good to continue
            if i > 0 and abs(s[i] - s[i - 1]) > k:
                return total
        # N itself is good
        return total + 1

    return count(r) - count(l - 1)
